package com.nexbank.fraud.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="fraud_alerts") public class FraudAlert {@Id private UUID id;@Column(name="transfer_id",nullable=false,unique=true)private UUID transferId;@Column(name="account_id",nullable=false)private UUID accountId;@Column(name="user_id")private UUID userId;@Column(nullable=false)private int score;@Column(nullable=false)private String reasons;@Column(name="ai_explanation")private String aiExplanation;@Column(nullable=false)private String status;@Column(name="reviewed_by")private UUID reviewedBy;@Column(name="created_at",nullable=false)private Instant createdAt;protected FraudAlert(){}public FraudAlert(UUID transfer,UUID account,UUID user,int score,String reasons,String explanation){id=UUID.randomUUID();transferId=transfer;accountId=account;userId=user;this.score=score;this.reasons=reasons;aiExplanation=explanation;status="NEW";createdAt=Instant.now();}public UUID getId(){return id;}public UUID getTransferId(){return transferId;}public UUID getAccountId(){return accountId;}public UUID getUserId(){return userId;}public int getScore(){return score;}public String getReasons(){return reasons;}public String getAiExplanation(){return aiExplanation;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public void review(String status,UUID reviewer){this.status=status;reviewedBy=reviewer;}}
